//! Minimal re-implementation of the parts of `tsl::hopscotch_map` used by the
//! tests, backed by the standard library. A hopscotch map stores unique keys,
//! so `equal_range` covers at most one element.

use std::collections::HashMap;

pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: std::hash::Hash + Eq,
{
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) {
        self.inner.insert(key, value);
    }

    /// Returns `(first, last)` where `[first, last)` contains every element
    /// whose key equals `key` (zero or one element for a unique-key map).
    pub fn equal_range(&self, key: &K) -> (Iter<'_, K, V>, Iter<'_, K, V>) {
        let mut first = Iter { current: None };
        let last = Iter { current: None };
        if let Some(pair) = self.inner.get_key_value(key) {
            first.current = Some(pair);
        }
        (first, last)
    }
}

pub struct Iter<'a, K, V> {
    current: Option<(&'a K, &'a V)>,
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        self.current.take()
    }
}

impl<'a, K, V> PartialEq for Iter<'a, K, V> {
    fn eq(&self, other: &Self) -> bool {
        match (&self.current, &other.current) {
            (None, None) => true,
            (Some(a), Some(b)) => std::ptr::eq(a.0, b.0),
            _ => false,
        }
    }
}

impl<'a, K, V> Eq for Iter<'a, K, V> {}

