mod hopscotch_map;

use hopscotch_map::HopscotchMap;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut count: i32 = 15;
    if args.len() > 1 && args[1] == "--a" {
        count = args[2].parse().expect("invalid integer");
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    for i in 0..count {
        map.insert(i, i * 12);
    }

    let key = count / 2;
    let (first, last) = map.equal_range(&key);
    let mut num_in_range = 0;
    let mut it = first;
    while it != last {
        it.next();
        num_in_range += 1;
    }

    println!("{}", num_in_range);
}

